using System;using System.Drawing;using System.Windows.Forms;
namespace LoopFive {
 public class EditorGrid:TableLayoutPanel {
  public EditorGrid(){Dock=DockStyle.Top;AutoSize=true;ColumnCount=2;Padding=new Padding(14);ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,205));ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));BackColor=Theme.Background;}
  public void Row(string title,Control c){int row=RowCount++;RowStyles.Add(new RowStyle(SizeType.AutoSize));Label l=Theme.Label(title);l.MaximumSize=new Size(195,0);Controls.Add(l,0,row);c.Margin=new Padding(5,5,5,7);c.Anchor=AnchorStyles.Left|AnchorStyles.Right;Controls.Add(c,1,row);}
  public void Note(string text){Label l=Theme.Label(text);l.MaximumSize=new Size(760,0);l.AutoSize=true;int row=RowCount++;Controls.Add(l,0,row);SetColumnSpan(l,2);}
  public CheckBox Bool(string label,bool value,Action<bool> changed){CheckBox c=Theme.Check("");c.Checked=value;c.CheckedChanged+=delegate{changed(c.Checked);};Row(label,c);return c;}
  public NumericUpDown Number(string label,float value,float min,float max,Action<float> changed,int decimals){NumericUpDown n=Theme.Number((decimal)min,(decimal)max,(decimal)MathX.Clamp(value,min,max));n.DecimalPlaces=decimals;n.Increment=decimals>0?.1M:1;n.ValueChanged+=delegate{changed((float)n.Value);};Row(label,n);return n;}
  public ComboBox Choice(string label,string[] values,int selected,Action<int> changed){ComboBox c=Theme.Combo(values);c.SelectedIndex=Math.Max(0,Math.Min(values.Length-1,selected));c.SelectedIndexChanged+=delegate{changed(c.SelectedIndex);};Row(label,c);return c;}
  public TextBox TextRow(string label,string text,Action<string> changed){TextBox t=new TextBox{Text=text,BackColor=Theme.Panel,ForeColor=Theme.Text,BorderStyle=BorderStyle.FixedSingle,MaxLength=80};t.TextChanged+=delegate{changed(t.Text);};Row(label,t);return t;}
 }
 public class TrackDialog:Form {
