   grid.Bool("Inicio con fundido",t.FadeIn,delegate(bool b){Change(delegate{t.FadeIn=b;});});grid.Number("Fundido de entrada (pulsos)",t.FadeInBeats,.0625f,256,delegate(float v){Change(delegate{t.FadeInBeats=v;});},2);grid.Choice("Al detener",new string[]{"Inmediatamente","Fundido de salida","Al final del loop"},t.StopMode,delegate(int v){Change(delegate{t.StopMode=v;});});grid.Number("Fundido de salida (pulsos)",t.FadeOutBeats,.0625f,256,delegate(float v){Change(delegate{t.FadeOutBeats=v;});},2);
