   FlowLayoutPanel tools=new FlowLayoutPanel{AutoSize=true};AddTool(tools,"Importar WAV",delegate{import(i);});AddTool(tools,"Exportar WAV",delegate{export(i);});AddTool(tools,"Normalizar",Normalize);AddTool(tools,"Ajustar a compases",Fit);AddTool(tools,"MARK",delegate{e.Mark(i,false);});AddTool(tools,"MARK BACK",delegate{e.Mark(i,true);});AddTool(tools,"Rehacer",delegate{e.Undo(i,true);});AddTool(tools,"Borrar",delegate{if(UiMessage.Show("¿Borrar el audio de esta pista? Puedes recuperarlo con Deshacer.","Borrar pista",MessageBoxButtons.YesNo)==DialogResult.Yes)e.Clear(i);});grid.Row("Herramientas",tools);
