   grid.Note("Los ajustes se aplican al instante. Reversa y One Shot desactivan la sobregrabación. XFADE usa estiramiento granular y puede producir artefactos. El bounce toma las pistas antes de los efectos globales de reproducción.");Button close=Theme.Button("Cerrar",delegate{Close();});close.Dock=DockStyle.Bottom;close.Height=40;Controls.Add(close);FormClosed+=delegate{refresh();};
  }
  static int MeasureIndex(int m){int[] all={-1,0,1,2,4,8,16,32,64};int i=Array.IndexOf(all,m);return i<0?0:i;}
  void AddTool(FlowLayoutPanel p,string text,Action action){Button b=Theme.Button(text,action);b.Width=120;p.Controls.Add(b);}
  void Change(Action a){lock(engine.Gate){a();engine.Dirty=true;}}
  void Normalize(){lock(engine.Gate){Track t=engine.Tracks[index];if(t.Clip==null)return;t.Snapshot();float peak=0;for(int i=0;i<t.Clip.Length;i++)peak=Math.Max(peak,Math.Max(Math.Abs(t.Clip.L[i]),Math.Abs(t.Clip.R[i])));if(peak>.00001f)for(int i=0;i<t.Clip.Length;i++){t.Clip.L[i]*=.95f/peak;t.Clip.R[i]*=.95f/peak;}engine.Dirty=true;}}
  void Fit(){lock(engine.Gate){Track t=engine.Tracks[index];if(t.Clip==null)return;int bars=t.Config.Measures>0?t.Config.Measures:Math.Max(1,(int)Math.Round(t.Clip.Length/44100.0*engine.Config.Bpm/60/engine.BarBeats));int n=(int)Math.Round(bars*engine.BarBeats*44100*60/engine.Config.Bpm);if(n>Engine.MaxSamples)throw new Exception("Duración superior a 10 minutos.");t.Snapshot();float[] l=new float[n],r=new float[n];Array.Copy(t.Clip.L,l,Math.Min(n,t.Clip.Length));Array.Copy(t.Clip.R,r,Math.Min(n,t.Clip.Length));t.Clip=new AudioClip(l,r,engine.Config.Bpm,bars*engine.BarBeats);t.Stop();engine.Dirty=true;}}
